import { A11yModule } from '@angular/cdk/a11y';
import { BreakpointObserver, BreakpointState } from '@angular/cdk/layout';
import { NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChild,
  ElementRef,
  EventEmitter,
  HostBinding,
  Input,
  OnInit,
  Output,
  TemplateRef,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import { QButtonComponent } from '@questrade/allspark-angular-components/button';
import { QScrollShadowDirective } from '@questrade/allspark-angular-components/core/directives';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QInteractiveIconComponent } from '@questrade/allspark-angular-components/interactive-icon';
import { QPopoverDirective } from '@questrade/allspark-angular-components/popover';
import { QSkeletonComponent } from '@questrade/allspark-angular-components/skeleton';
import { QSpinnerComponent, QSpinnerSize } from '@questrade/allspark-angular-components/spinner';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { arrowBack, clear } from '@questrade/allspark-icons/icons';
import { takeUntil } from 'rxjs';
import { QAdvancedDropdownOriginDirective } from './advanced-dropdown-origin.directive';
import { QAdvancedDropdownLoadingVariant } from './types/advanced-dd-loading-variant.type';
import { QFooterButtons } from './types/footer-buttons.type';

@Component({
  imports: [
    NgTemplateOutlet,
    QInteractiveIconComponent,
    QButtonComponent,
    A11yModule,
    TranslocoModule,
    QScrollShadowDirective,
    QSpinnerComponent,
    QSkeletonComponent,
  ],
  selector: 'q-advanced-dropdown',
  templateUrl: './advanced-dropdown.component.html',
  styleUrls: ['./advanced-dropdown.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  providers: [QDestroyService, MISSING_KEY_HANDLER, ALLSPARK_SCOPE],
  hostDirectives: [
    {
      directive: QPopoverDirective,
      inputs: ['qPopoverOffset: offset', 'qPopoverPlacement: placement'],
    },
  ],
})
export class QAdvancedDropdownComponent implements OnInit, AfterViewInit {
  @Output() readonly primaryButtonClicked = new EventEmitter<Event>();
  @Output() readonly secondaryButtonClicked = new EventEmitter<Event>();
  @Output() readonly linkClicked = new EventEmitter<Event>();
  @Output() readonly opened = new EventEmitter<void>();
  @Output() readonly closed = new EventEmitter<void>();

  @Input() title = '';
  @Input() linkButtonText = '';
  @Input() secondaryButtonText = '';
  @Input() primaryButtonText = '';
  @Input() footerButtons: QFooterButtons = 'dual';
  @Input() loadingVariant: QAdvancedDropdownLoadingVariant = 'spinner';
  @Input() loadingSpinnerSize: QSpinnerSize = 'medium';
  @Input() loadingSkeletonTemplate: TemplateRef<unknown> | null = null;
  @Input({ transform: booleanAttribute }) showHeaderIcon = true;
  @Input({ transform: booleanAttribute }) showHeader = true;
  @Input({ transform: booleanAttribute }) showFooter = true;
  @Input({ transform: booleanAttribute }) showSecondaryButton = true;
  @Input({ transform: booleanAttribute }) fitTriggerWidth = false;
  @Input({ transform: booleanAttribute }) loading = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-advanced-dropdown';

  @Input() get dropdownTrigger(): QAdvancedDropdownOriginDirective | null {
    return this._dropdownTrigger;
  }
  set dropdownTrigger(value: QAdvancedDropdownOriginDirective | null) {
    if (!value) return;

    this._dropdownTrigger = value;
    this._popoverDirective.setPopoverTriggerElement(value.elementRef.nativeElement);
  }

  @ContentChild('dropdownContentTemplate') _dropdownContentTemplate!: TemplateRef<HTMLElement>;

  @HostBinding('class') readonly _rootClass = [
    'q-advanced-dropdown',
    'q-advanced-dropdown-overlay-panel',
  ].join(' ');
  @HostBinding('attr.popover') _popoverAttr = '';

  isMobileView = false;
  isOpened = false;

  private _dropdownTrigger: QAdvancedDropdownOriginDirective | null = null;
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _breakpointObserver = inject(BreakpointObserver);
  private readonly _popoverDirective = inject(QPopoverDirective);
  private readonly _elementRef = inject(ElementRef);

  constructor() {
    this._popoverDirective.placement = 'bottom-start';
  }

  ngOnInit(): void {
    this._iconRegistry.registerIcons([clear, arrowBack]);
  }

  ngAfterViewInit(): void {
    this._breakpointObserver
      .observe(['(max-width: 599px)'])
      .pipe(takeUntil(this._destroy$))
      .subscribe((result: BreakpointState) => {
        this.isMobileView = result.matches;
        this._popoverDirective._hostClass = this.isMobileView ? '' : 'q-popover-directive';
        this._popoverDirective._positioningDisabled.set(this.isMobileView);
        this._fitContainerToTrigger();

        this._cdr.markForCheck();
      });

    this._popoverDirective.opened.subscribe(() => {
      this.isOpened = true;
      this.opened.emit();
    });

    this._popoverDirective.closed.subscribe(() => {
      this.isOpened = false;
      this.closed.emit();
    });
  }

  open(): void {
    this._fitContainerToTrigger();
    this._elementRef.nativeElement.showPopover({
      source: this.dropdownTrigger?.elementRef.nativeElement,
    });
  }

  close(): void {
    this._elementRef.nativeElement.hidePopover();
  }

  /**
   * @param force A boolean, which causes toggle to behave like open or close.
   * If set to true, the advanced dropdown is opened if it was initially closed. If it was initially opened, nothing happens.
   * If set to false, the advanced dropdown is closed if it was initially opened. If it was initially closed, nothing happens.
   */
  toggle(force = false): void {
    this._elementRef.nativeElement.togglePopover({
      source: this.dropdownTrigger?.elementRef.nativeElement,
      force,
    });
  }

  onPrimaryButtonClick(event: Event): void {
    this.primaryButtonClicked.emit(event);
  }

  onSecondaryButtonClick(event: Event): void {
    this.secondaryButtonClicked.emit(event);
  }

  onLinkClicked(event: Event): void {
    this.linkClicked.emit(event);
  }

  get isSkeleton(): boolean {
    return this.loadingVariant === 'skeleton';
  }

  private _fitContainerToTrigger(): void {
    if (this.isMobileView) {
      this._elementRef.nativeElement.style.setProperty(
        '--awds-advanced-dropdown-container-width',
        '100%',
      );
      return;
    }
    if (this.fitTriggerWidth) {
      this._elementRef.nativeElement.style.setProperty(
        '--awds-advanced-dropdown-container-width',
        `${this.dropdownTrigger?.elementRef.nativeElement.clientWidth}px`,
      );
    } else {
      this._elementRef.nativeElement.style.removeProperty(
        '--awds-advanced-dropdown-container-width',
      );
    }
  }
}
